func TestRunDryRunWithoutCredentials(t *testing.T) {
	t.Parallel()

	var stdout, stderr bytes.Buffer
	runner := &stubRunner{}
	code := runWithRunner(&stdout, &stderr, func(key string) string {
		switch key {
		case "SEMREL_VERSION":
			return "v1.2.3"
		case "SEMREL_DRY_RUN":
			return "true"
		case "SEMREL_PLUGIN_CARGO_PACKAGE":
			return "crate-a"
		default:
			return ""
		}
	}, runner)

	require.Equal(t, 0, code)
	require.Equal(t, 0, runner.called)
	require.True(t, strings.HasPrefix(stderr.String(), "plugin_schema_version=1\n"))
	require.Contains(t, stderr.String(), "[dry-run] publisher-crates: would need CARGO_REGISTRY_TOKEN")
	require.Contains(t, stderr.String(), "[dry-run] publisher-crates: would publish crate-a@1.2.3")
	require.Contains(t, stdout.String(), "cargo publish --package crate-a --dry-run")
	require.Contains(t, stdout.String(), "publisher-crates: dry-run validation completed for 1 package(s)")
}

func TestRunDryRunWithCredentials(t *testing.T) {
	t.Parallel()

	var stdout, stderr bytes.Buffer
	runner := &stubRunner{}
	code := runWithRunner(&stdout, &stderr, func(key string) string {
		switch key {
		case "SEMREL_VERSION":
			return "1.2.3"
		case "SEMREL_DRY_RUN":
			return "true"
		case "CARGO_REGISTRY_TOKEN":
			return "secret-token"
		default:
			return ""
		}
	}, runner)

	require.Equal(t, 0, code)
	require.Equal(t, 0, runner.called)
	require.True(t, strings.HasPrefix(stderr.String(), "plugin_schema_version=1\n"))
	require.NotContains(t, stderr.String(), "would need")
	require.Contains(t, stderr.String(), "[dry-run] publisher-crates: would publish crate@1.2.3")
	require.Contains(t, stdout.String(), "cargo publish --dry-run")
	require.Contains(t, stdout.String(), "publisher-crates: dry-run validation completed")
	require.NotContains(t, stdout.String(), "secret-token")
	require.NotContains(t, stderr.String(), "secret-token")
}

